--- a/src/service.ts
+++ b/src/service.ts
@@ -1,8 +1,30 @@
-import type { ZoneRules } from "./zone.ts";
+import { ZoneError, parseZone, type ZoneRules } from "./zone.ts";

 export const ZONES_URL = "https://tzdata.ops.internal/v1/zones";

+const ZONE_NAME = /^[A-Za-z_]+(\/[A-Za-z0-9_+-]+)+$/;
+
 /** Load the rules of a zone from the tz service. */
 export async function fetchZone(name: string): Promise<ZoneRules> {
-  throw new Error("not implemented");
+  if (typeof name !== "string" || !ZONE_NAME.test(name)) {
+    throw new RangeError(`invalid zone name: ${JSON.stringify(name)}`);
+  }
+
+  let response: Response;
+  try {
+    response = await fetch(`${ZONES_URL}/${name}`);
+  } catch (err) {
+    throw new ZoneError(`tz service unavailable: ${err instanceof Error ? err.message : String(err)}`);
+  }
+  if (!response.ok) {
+    throw new ZoneError(`tz service unavailable: HTTP ${response.status}`);
+  }
+
+  let body: unknown;
+  try {
+    body = await response.json();
+  } catch {
+    throw new ZoneError("tz service answer is not JSON");
+  }
+  return parseZone(body);
 }
